//! Replay of SciPy's recorded BFGS runs through the `BfgsState` ask/tell machine.
//!
//! Validates: the port of `_minimize_bfgs` + the `wolfe1` branch of `_line_search_wolfe12`
//! against SciPy 1.16.3 (`scipy/optimize/_optimize.py`, `_linesearch.py`, commit
//! b9105ccc2237f57acb1060202cd77f6dd264fb34). The data is generated by
//! `scripts/gen_minimize_bfgs_reference.py` (see `tests/data/bfgs/README.md`, which derives every
//! tolerance used here). Only runs with `parity = true` are replayed: `wolfe2_calls == 0` and a
//! finite path; the fallback and non-finite runs are covered in `bfgs_termination.rs`.
//!
//! Each recorded `(f, g)` is fed to `tell`, so no objective is evaluated. Per run:
//!
//! | Quantity | Claim | Bound |
//! |---|---|---|
//! | requested point of every evaluation in the run's comparison prefix | SciPy's `i`-th evaluation point | derived bound `C ε x_scale + 2 x_slack` (running magnitude scale, SciPy's own direction error), C = 32 calibrated |
//! | evaluation count, iteration count, termination | equal | exact |
//! | final `f` | SciPy's | exact (the replay feeds it) |
//! | final iterate (runs whose prefix is the whole run) | SciPy's `final_x` | the same bound at the last evaluation |
//! | final `H` (runs flagged `h_compared`) | SciPy's `hess_inv` and the exact (mpmath) matrix | `C ε max‖H‖` |
//!
//! Evaluation counts are expected equal; a mismatch is investigated and reported in the PR with its
//! reason, not relaxed here. Do not loosen a tolerance without writing why.
//!
//! The recorded runs include `rosen2_maxiter_eq_nit`: SciPy reports "maximum number of iterations"
//! (status 1) for a run that converges on its last allowed iteration, because `k >= maxiter` is
//! tested after the loop. The expected termination there is `MaxIter` (open question 2 of the PR).
//!
//! Status in the red stage: `data_is_consistent` passes (it only reads the data); every replay
//! fails, because the stub ends every run before the first evaluation.

mod bfgs_common;

use bfgs_common::*;
use minimize::bfgs::Termination;

fn check_run(id: &str) {
    let run = run_by_id(id);
    assert!(run.parity, "{id}: not a parity run");
    let rep = replay(&run, None);
    let mut errors: Vec<String> = Vec::new();
    let cmp = run
        .cmp_nsearch
        .expect("parity runs record their comparison prefix");
    let whole_run = cmp == run.n_ls;

    // 1. requested points, by value on the comparison prefix (the bound models rounding, not its amplification by the
    //    problem: past the prefix only counts and termination are compared)
    let mut compared = 0;
    for (i, x) in rep.asked.iter().enumerate() {
        let want = &run.evals[i];
        if want.search.expect("parity evals carry their search") >= cmp && i > 0 {
            break; // later points differ as a consequence; counts and termination below cover the rest
        }
        let scale = want.x_scale.as_ref().expect("x_scale");
        let slack = want.x_slack.as_ref().expect("x_slack");
        compared += 1;
        if let Some(m) = mismatch(&format!("eval {i}: x"), x, &want.x, scale, slack) {
            errors.push(m);
            break;
        }
    }
    // 2. counts and termination, on the whole run
    match rep.termination {
        None => errors.push(format!(
            "asked for more evaluations than SciPy's {} (after {})",
            run.nfev,
            rep.asked.len()
        )),
        Some(t) => {
            if t != run.expected_termination() {
                errors.push(format!(
                    "termination {t:?}, SciPy {:?} (status {}, \"{}\")",
                    run.expected_termination(),
                    run.status,
                    run.message
                ));
            }
        }
    }
    if rep.asked.len() != run.nfev {
        errors.push(format!(
            "{} evaluations asked, SciPy made {}",
            rep.asked.len(),
            run.nfev
        ));
    }
    if rep.state.evaluations() != run.nfev {
        errors.push(format!(
            "state.evaluations() = {}, SciPy {}",
            rep.state.evaluations(),
            run.nfev
        ));
    }
    if rep.state.iterations() != run.nit {
        errors.push(format!(
            "state.iterations() = {}, SciPy nit {}",
            rep.state.iterations(),
            run.nit
        ));
    }
    // one direction per started iteration: nit of them (the converging step starts none)
    if rep.directions.len() != run.nit {
        errors.push(format!(
            "{} iterations started, SciPy ran {}",
            rep.directions.len(),
            run.nit
        ));
    }
    // 3. final f exactly (the replay feeds it); final iterate and H only where the whole run is inside the claim
    if rep.state.f() != run.final_f {
        errors.push(format!(
            "final f {:e}, SciPy {:e}",
            rep.state.f(),
            run.final_f
        ));
    }
    if whole_run {
        let last = run.evals.last().expect("evaluations");
        let (scale, slack) = (
            last.x_scale.as_ref().expect("x_scale"),
            last.x_slack.as_ref().expect("x_slack"),
        );
        if let Some(m) = mismatch("final x", rep.state.x(), &run.final_x, scale, slack) {
            errors.push(m);
        }
        if let Some(h) = run.hess.as_ref().filter(|h| h.h_compared) {
            let got = matrix_of(&rep.state);
            let scale = vec![h.h_scale; got.len()];
            for (label, want) in [("h_exact", &h.h_exact), ("h_scipy", &h.h_scipy)] {
                if let Some(m) = mismatch(&format!("final H vs {label}"), &got, want, &scale, &[]) {
                    errors.push(m);
                }
            }
        }
    }
    eprintln!(
        "{id}: {compared} of {} evaluations compared by value (prefix {cmp} of {} searches), counts and termination on all",
        run.nfev, run.n_ls
    );
    assert!(errors.is_empty(), "{id}:\n  {}", errors.join("\n  "));
}

macro_rules! replay_tests {
    ($($name:ident),* $(,)?) => {
        $(
            #[test]
            fn $name() {
                check_run(stringify!($name));
            }
        )*

        /// The macro's list is the data's list of parity runs: a run added to the data needs a test.
        #[test]
        fn every_parity_run_has_a_replay_test() {
            let mut listed: Vec<&str> = vec![$(stringify!($name)),*];
            listed.sort_unstable();
            let mut recorded: Vec<String> = load_runs()
                .into_iter()
                .filter(|r| r.parity)
                .map(|r| r.id)
                .collect();
            recorded.sort_unstable();
            assert_eq!(listed, recorded);
        }
    };
}

replay_tests!(
    rosen2_a,
    rosen2_b,
    rosen2_c,
    rosen2_tight,
    rosen5,
    himmelblau,
    beale,
    powell,
    quad5,
    quad10_k1e2,
    quad10_k1e4,
    stationary,
    rosen2_xrtol,
    rosen2_maxiter_eq_nit,
    rosen2_maxiter1,
    rosen2_maxiter5,
);

#[test]
fn data_is_consistent() {
    let runs = load_runs();
    assert!(runs.len() >= 20, "{} runs", runs.len());
    for r in &runs {
        assert_eq!(
            r.evals.len(),
            r.nfev,
            "{}: nfev vs recorded evaluations",
            r.id
        );
        assert!(r.iters.len() >= r.nit, "{}: line searches vs nit", r.id);
        assert_eq!(r.x0, r.evals[0].x, "{}: the first evaluation is x0", r.id);
        assert_eq!(
            r.parity,
            r.group == "finite" && r.wolfe2_calls == 0,
            "{}",
            r.id
        );
        if r.parity {
            // one evaluation per trial, and every update the run applied had yᵀs > 0 (strong Wolfe steps only)
            assert_eq!(r.cache_hits, 0, "{}: SciPy skipped evaluations", r.id);
            assert_eq!((r.n_rho1000, r.n_ys_nonpos), (0, 0), "{}", r.id);
            assert!(r.hess.is_some(), "{}: parity runs record the final H", r.id);
            // the calibration is data: inside the comparison prefix the mirror's ratio stays a quarter of C, and the
            // prefix is not empty (it keeps PREFIX_MARGIN = 2 searches below the first search outside the bound)
            assert!(
                r.x_ratio_max <= REPLAY_C / 4.0,
                "{}: ratio maximum {}",
                r.id,
                r.x_ratio_max
            );
            let cmp = r.cmp_nsearch.expect("cmp_nsearch");
            assert!(
                cmp <= r.n_ls && cmp >= r.n_ls.min(1),
                "{}: prefix {cmp} of {}",
                r.id,
                r.n_ls
            );
            assert!(r.evals.iter().all(|e| e.x_scale.is_some()), "{}", r.id);
        }
        // the fallback runs record where wolfe2 began; the others do not
        assert_eq!(
            r.wolfe2_first_eval.is_some(),
            r.wolfe2_calls > 0,
            "{}",
            r.id
        );
    }
    // the SciPy probe: BFGS finishes the 5-dim quadratic in n = 5 iterations
    let q = runs.iter().find(|r| r.id == "quad5").expect("quad5");
    assert_eq!((q.nit, q.nfev), (5, 11));
    assert_eq!(q.expected_termination(), Termination::GradTol);
}
